{
  "technical_and_design_decisions": [
    "U1 (Admin UI Job Creation): Investigate Admin UI REST endpoint calls versus Shell execution; fix missing log output by adding explicit exception logging in the job admin REST controllers and resolve role-based access control discrepancies for ROLE_CREATE and ROLE_ADMIN.",
    "U2 (Explicit Partition Count): Extend stream deployment properties and message bus binding configuration to accept an explicit partitionCount setting for deterministic consumer module routing.",
    "U3 (Kafka Dynamic Partitions): Update the Kafka source module to support topic pattern regex/dynamic partition discovery and subscription using updated Kafka consumer client capabilities.",
    "U4 (HDFS Syncable Writes): Add an optional `syncable` boolean configuration to the HDFS sink module that calls Hadoop `Syncable.hflush()` or `hsync()` on file output streams upon write.",
    "U5 (HDFS Direct Writes): Introduce an `enableInUseSuffix` boolean option in HDFS sink (default true) which, when set to false, writes directly to target filenames without creating temporary `.tmp` extensions.",
    "U6 (Build Tool Plugins): Develop/extend Maven Mojo and Gradle tasks that interact with Spring XD REST API endpoints to register and upload custom module binaries.",
    "U7 (Module Versioning): Update module registry storage (e.g., ZooKeeper/repository), module coordinates (`type:name:version`), and deployment manager resolution logic to support semantic versioning.",
    "U8 (PHD 3.0 Certification): Update Hadoop/ODP dependencies to PHD 3.0 baseline versions and validate execution across HDFS, YARN, and MapReduce workloads."
  ],
  "assumptions": [
    "Development and testing environment includes access to a local or remote PHD 3.0 / ODP Hadoop cluster and a Kafka broker cluster.",
    "The software developer is solely responsible for requirements analysis, implementation, unit testing, integration testing, and documentation.",
    "Spring XD Admin REST APIs exist for module upload and can be leveraged directly by Maven and Gradle build plugins.",
    "All effort estimates are calculated in single-developer work-hours without accounting for calendar downtime or external dependencies."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Admin UI Job Creation Bug Investigation and Fix (U1)",
      "activity_description": "Debug Admin UI job creation workflow against REST controller authorization checks, improve container logging for unhandled UI exceptions, and align permissions for ROLE_CREATE and ROLE_ADMIN.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Explicit Partition Count Configuration Support (U2)",
      "activity_description": "Implement configuration option to explicitly set partition count during stream module deployment and integrate payload routing logic across message bus bindings.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Kafka Source Dynamic Partition Subscription (U3)",
      "activity_description": "Enhance Kafka source module options to support pattern-based topic and dynamic partition subscription, updating the underlying adapter and listener containers.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "HDFS Sink Syncable Writes Option (U4)",
      "activity_description": "Add `syncable` write mode to HDFS sink, invoking `Syncable.hflush()` / `hsync()` on Hadoop FS output streams for improved stream durability.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "HDFS Sink Direct File Writing Support (U5)",
      "activity_description": "Implement option to disable `inUseSuffix` (`.tmp`) in HDFS sink, permitting direct writes to destination paths for failure resiliency.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Maven and Gradle Plugins for Custom Module Upload (U6)",
      "activity_description": "Create Maven Mojo and Gradle plugin tasks to package and push custom module archives directly to the Spring XD Admin server via REST endpoints.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Custom Module Versioning & Lifecycle Management (U7)",
      "activity_description": "Extend module repository and deployment engine to handle module versioning, allowing side-by-side versions, upgrades, and resolution by version coordinates.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "PHD 3.0 / ODP Certification and Compatibility (U8)",
      "activity_description": "Update project dependency management for Pivotal HD 3.0 / ODP stack, resolve API/version conflicts, and verify compatibility across HDFS and YARN integrations.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Integration Testing, Documentation, and Release Packaging",
      "activity_description": "Execute full regression test suite across updated components, write user documentation for new configuration options, and prepare the software increment release.",
      "most_likely_effort": 20
    }
  ],
  "reported_total": {
    "most_likely_effort": 182
  }
}
